-- ============================================================
-- ISLAND 6: STRINGS AND DECISIONS  (Chapter 9 + Chapter 10)
-- 20 levels. Lesson ids 179-198, module_id 6.
-- Levels 1-12  = Chapter 9 (String Handling Methods)
-- Levels 13-20 = Chapter 10 (Decision Control Structures)
-- ============================================================

-- 1) The lessons table has a foreign key to lesson_modules, so module 6 must exist first.
--    (Copy the column list from your own module 5 row. Example only, adjust the columns to match your table:)
-- INSERT INTO `lesson_modules` (`id`, `title`, ...) VALUES (6, 'Strings and Decisions', ...);

-- If a run stops with "#1406 Data too long for column ...", check the column sizes with
--   SHOW COLUMNS FROM `lessons`;
-- and widen the short ones (keep NOT NULL if your table has it), for example:
-- ALTER TABLE `lessons` MODIFY `required_code_label` VARCHAR(255), MODIFY `required_code_pattern` VARCHAR(500), MODIFY `goal` VARCHAR(500), MODIFY `solution_code` VARCHAR(500);

-- 2) Clear any existing Island 6 rows so re-running this file never hits
--    "Duplicate entry '6-1' for key 'uq_lessons_module_order'".
--    First look at what is there:
--      SELECT id, module_id, order_index, title FROM lessons WHERE module_id = 6 OR id >= 179;
-- Removes the old Island 6 snippets, including any old rows that sit on ids 179-198
-- under a different module_id (those would otherwise cause a primary-key error).
DELETE FROM `lessons` WHERE `module_id` = 6 OR `id` BETWEEN 179 AND 198;

-- OPTIONAL: if players already have saved progress for the OLD lessons 179-198, the new
-- levels would show as already completed. Clear it with your progress table's real name, e.g.:
-- DELETE FROM `user_progress` WHERE `lesson_id` BETWEEN 179 AND 198;

-- 3) The lessons
INSERT INTO `lessons` (`id`, `module_id`, `level_label`, `track`, `title`, `briefing`, `hint`, `goal`, `xp_reward`, `target_tiles`, `order_index`, `is_active`, `created_at`, `min_moves`, `min_says`, `min_jumps`, `required_code_label`, `required_code_pattern`, `background_image`, `subtitle`, `description`, `grid_cols`, `grid_rows`, `mechanics_config`, `total_tiles`, `ground_fraction`, `initial_tile`, `flag_tile`, `solution_code`, `line_breakdown`) VALUES
(179, 6, 'Level 1', 'STRINGS AND DECISIONS', 'The Letter Locker', 'Pip reaches Crossroads Isle, where every locker opens with a single letter. A string is a sequence of characters, and string manipulation is the basis of many algorithms and utilities, such as input validation and text analysis. The charAt(anIndex) method returns the character at the position anIndex. Positions start counting at 0, so in "SEPTEMBER" the character at index 3 is T.

Declare a String named myString set to "SEPTEMBER", then store the character at index 3 in a char named location.', 'Index 3 is the fourth letter, because counting starts at 0.', 'String myString = "SEPTEMBER"; char location = myString.charAt(3);', 50, 8, 1, 1, '2026-10-10 08:00:00', 0, 0, 0, 'Use the exact solution: String myString = "SEPTEMBER"; char location = myString.charAt(3);', 'String\\s+myString\\s+=\\s+"SEPTEMBER";\\s+char\\s+location\\s+=\\s+myString\\.charAt\\(\\s*3\\s*\\);', '/assets/landscapes/oakheart1.png', 'charAt()', 'Pip reaches Crossroads Isle, where every locker opens with a single letter. A string is a sequence of characters, and string manipulation is the basis of many algorithms and utilities, such as input validation and text analysis. The charAt(anIndex) method returns the character at the position anIndex. Positions start counting at 0, so in "SEPTEMBER" the character at index 3 is T.

Declare a String named myString set to "SEPTEMBER", then store the character at index 3 in a char named location.', 10, 1, '{"tile_elevations": {}}', 10, 0.78000000, 1, 8, 'String myString = "SEPTEMBER"; char location = myString.charAt(3);', '[{"part": "String myString = \\"SEPTEMBER\\";", "explanation": "Declares a String variable and stores the word in it."}, {"part": "char location", "explanation": "A char variable, because charAt() returns a single character."}, {"part": "myString.charAt(3)", "explanation": "Returns the character at index 3, which is T."}, {"part": ";", "explanation": "Ends the statement."}]'),
(180, 6, 'Level 2', 'STRINGS AND DECISIONS', 'The Word Measure', 'A scribe measures every word that enters the isle. The length() method counts the number of characters in a string and returns the length of myString as an int. Notice that length() has parentheses, because it is a method. "SEPTEMBER" has 9 characters.

Declare a String named myString set to "SEPTEMBER", then store its length in an int named size.', 'length() needs parentheses after it.', 'String myString = "SEPTEMBER"; int size = myString.length();', 50, 8, 2, 1, '2026-10-10 08:00:00', 0, 0, 0, 'Use the exact solution: String myString = "SEPTEMBER"; int size = myString.length();', 'String\\s+myString\\s+=\\s+"SEPTEMBER";\\s+int\\s+size\\s+=\\s+myString\\.length\\(\\s*\\s*\\);', '/assets/landscapes/oakheart2.png', 'length()', 'A scribe measures every word that enters the isle. The length() method counts the number of characters in a string and returns the length of myString as an int. Notice that length() has parentheses, because it is a method. "SEPTEMBER" has 9 characters.

Declare a String named myString set to "SEPTEMBER", then store its length in an int named size.', 10, 1, '{"tile_elevations": {}}', 10, 0.78000000, 1, 8, 'String myString = "SEPTEMBER"; int size = myString.length();', '[{"part": "String myString = \\"SEPTEMBER\\";", "explanation": "The string to measure."}, {"part": "int size", "explanation": "An int variable, because length() returns a whole number."}, {"part": "myString.length()", "explanation": "Counts the characters in myString, which gives 9."}, {"part": ";", "explanation": "Ends the statement."}]'),
(181, 6, 'Level 3', 'STRINGS AND DECISIONS', 'The Exact Match', 'Two guards compare passwords. The equals(aString) method returns true if aString exactly equals myString, and the resulting value is a boolean. Exactly means that uppercase and lowercase letters must match too, so "Java" and "java" are not equal.

Declare string1 as "Java" and string3 as "java", then store string1.equals(string3) in a boolean named same.', 'Call equals on string1 and put string3 inside the parentheses.', 'String string1 = "Java"; String string3 = "java"; boolean same = string1.equals(string3);', 50, 8, 3, 1, '2026-10-10 08:00:00', 0, 0, 0, 'Use the exact solution: String string1 = "Java"; String string3 = "java"; boolean same = string1.equals(string3);', 'String\\s+string1\\s+=\\s+"Java";\\s+String\\s+string3\\s+=\\s+"java";\\s+boolean\\s+same\\s+=\\s+string1\\.equals\\(\\s*string3\\s*\\);', '/assets/landscapes/oakheart3.png', 'equals()', 'Two guards compare passwords. The equals(aString) method returns true if aString exactly equals myString, and the resulting value is a boolean. Exactly means that uppercase and lowercase letters must match too, so "Java" and "java" are not equal.

Declare string1 as "Java" and string3 as "java", then store string1.equals(string3) in a boolean named same.', 10, 1, '{"tile_elevations": {}}', 10, 0.78000000, 1, 8, 'String string1 = "Java"; String string3 = "java"; boolean same = string1.equals(string3);', '[{"part": "String string1 = \\"Java\\"; String string3 = \\"java\\";", "explanation": "The two strings to compare."}, {"part": "boolean same", "explanation": "A boolean variable, because equals() returns true or false."}, {"part": "string1.equals(string3)", "explanation": "Checks whether the two strings match exactly. Here it is false because of the case."}, {"part": ";", "explanation": "Ends the statement."}]'),
(182, 6, 'Level 4', 'STRINGS AND DECISIONS', 'The Case Mirror', 'A mirror treats big and small letters as the same. The equalsIgnoreCase(aString) method is similar to equals but ignores case, so "Java" and "java" count as equal.

Declare string1 as "Java" and string3 as "java", then store string1.equalsIgnoreCase(string3) in a boolean named same.', 'The method name has a capital I and a capital C.', 'String string1 = "Java"; String string3 = "java"; boolean same = string1.equalsIgnoreCase(string3);', 50, 8, 4, 1, '2026-10-10 08:00:00', 0, 0, 0, 'Use the exact solution shown in the goal.', 'String\\s+string1\\s+=\\s+"Java";\\s+String\\s+string3\\s+=\\s+"java";\\s+boolean\\s+same\\s+=\\s+string1\\.equalsIgnoreCase\\(\\s*string3\\s*\\);', '/assets/landscapes/oakheart4.png', 'equalsIgnoreCase()', 'A mirror treats big and small letters as the same. The equalsIgnoreCase(aString) method is similar to equals but ignores case, so "Java" and "java" count as equal.

Declare string1 as "Java" and string3 as "java", then store string1.equalsIgnoreCase(string3) in a boolean named same.', 10, 1, '{"tile_elevations": {}}', 10, 0.78000000, 1, 8, 'String string1 = "Java"; String string3 = "java"; boolean same = string1.equalsIgnoreCase(string3);', '[{"part": "String string1 = \\"Java\\"; String string3 = \\"java\\";", "explanation": "The same two strings as before."}, {"part": "boolean same", "explanation": "Holds true or false."}, {"part": "string1.equalsIgnoreCase(string3)", "explanation": "Compares the strings while ignoring uppercase and lowercase, so the result is true."}, {"part": ";", "explanation": "Ends the statement."}]'),
(183, 6, 'Level 5', 'STRINGS AND DECISIONS', 'The First Finder', 'A seeker hunts for a letter inside a word. The indexOf(aCharacter) method searches for aCharacter and returns the index of its first occurrence within myString as an int. A failed search returns -1. There is also indexOf(aCharacter, beginIndex), which starts the search at beginIndex. In "SEPTEMBER" the first E is at index 1.

